from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parent.parent
GAMES=[('bunny-survival', 'Bunny Survival', 'SURVIVAL', 'ВЫЖИВАНИЕ', 'Small bunny. Endless courage.', 'Маленький кролик. Большая смелость.', 'Survive enemy waves, collect upgrades and build your village between battles. Move with WASD or arrow keys; your bunny attacks automatically. On mobile, play in landscape with the on-screen joystick. The demo is titled Rabbit run! in-game.', 'Выживайте среди волн врагов, собирайте улучшения и развивайте деревню между боями. Двигайтесь с помощью WASD или стрелок — кролик атакует автоматически. На телефоне играйте горизонтально с экранным джойстиком. Внутри демо игра называется «Заяц бежит!» (Rabbit run!).', '#dcedfb'),('bunny-runner','Bunny Runner','RUNNER','РАННЕР','A little bunny. A big adventure.','Маленький кролик. Большое приключение.','Three lanes, colorful worlds and one very speedy rabbit. Dodge obstacles, jump and dive into burrows to keep the adventure going.','Три полосы, красочные миры и один очень быстрый кролик. Обходите препятствия, прыгайте и ныряйте в норы навстречу приключениям.','#fff0b7'),('jelly-mix','Jelly Mix','MATCH PUZZLE','ТРИ В РЯД','A world worth brightening.','Мир, который хочется раскрасить.','Match colorful jellies, fill jars and meet helpful pets. Bring color back to the world across 300 levels.','Собирайте комбинации из желе, наполняйте банки и знакомьтесь с питомцами. Верните миру краски на протяжении 300 уровней.','#dceecb'),('ricochet','Ricochet: Neon Drive','ARCADE PUZZLE','АРКАДНАЯ ГОЛОВОЛОМКА','Find your perfect bounce.','Найдите идеальный рикошет.','Line up your shot and let it fly. Explore ricochet challenges and a second mirror-puzzle mode where every crystal needs to shine.','Прицельтесь и запускайте шар. Проходите испытания с рикошетами и головоломки с зеркалами, чтобы зажечь каждый кристалл.','#eadfff')]
for ru in (False,True):
 p='../' if ru else ''; folder=ROOT/'ru' if ru else ROOT; lang='ru' if ru else 'en'
 def t(en,rus): return rus if ru else en
 def shell(body,file='index.html',title=None):
  switch=('../'+file) if ru else ('ru/'+file)
  title=title or t('Small games. Big smiles.','Маленькие игры. Большие эмоции.')
  desc=t('Serendipity Games is a casual browser game studio, part of Serendipity Research. Explore our playable portfolio.','Serendipity Games — студия казуальных браузерных игр в составе Serendipity Research. Познакомьтесь с нашими демо.')
  return f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f6f1"><title>{escape(title)} — Serendipity Games</title><meta name="description" content="{desc}"><meta property="og:title" content="{escape(title)} — Serendipity Games"><meta property="og:description" content="{desc}"><meta property="og:image" content="https://serendipity-games.com/assets/studio-mascot.png"><link rel="canonical" href="https://serendipity-games.com/{'ru/' if ru else ''}{'' if file=='index.html' else file}"><link rel="alternate" hreflang="en" href="https://serendipity-games.com/{'' if file=='index.html' else file}"><link rel="alternate" hreflang="ru" href="https://serendipity-games.com/ru/{'' if file=='index.html' else file}"><link rel="icon" href="{p}assets/favicon.svg"><link rel="stylesheet" href="{p}style.css"><script defer src="{p}site.js"></script></head><body><a class="skip" href="#main">{t('Skip to content','К содержимому')}</a><header><a class="brand" href="./"><span class="brand-icon">✳</span><span>serendipity<small>GAMES</small></span></a><nav aria-label="{t('Main navigation','Основная навигация')}"><a href="./#games">{t('Our games','Наши игры')}</a><a href="./#studio">{t('The studio','О студии')}</a><a href="./#journal">{t('Inside the studio','Разработка')}</a></nav><div class="header-actions"><a class="language" href="{switch}" lang="{'en' if ru else 'ru'}" aria-label="{t('Switch to Russian','Switch to English')}">{t('RU','EN')}</a><a class="button small" href="./#partners">{t('Let’s connect','Партнёрам')} ↗</a><button class="motion" aria-pressed="false" aria-label="{t('Pause animations','Приостановить анимацию')}">Ⅱ</button></div></header><main id="main">{body}</main><footer><a class="brand" href="./"><span class="brand-icon">✳</span><span>serendipity<small>GAMES</small></span></a><p>{t('A little curiosity changes everything.','Всё начинается с любопытства.')}<br><span>{t('Part of','Часть')} Serendipity Research</span></p><div><a class="text-link" href="mailto:hello@serendipity-games.com">hello@serendipity-games.com</a><br>© 2026 Serendipity Games<br>{t('All rights reserved.','Все права защищены.')}</div></footer></body></html>'''
 cards=''
 for i,g in enumerate(GAMES):
  slug,name,genre,gr,tag,tr,desc,dr,color=g
  cards+=f'''<article class="game-card reveal" style="--card:{color}"><a class="game-art" href="{slug}.html"><img src="{p}assets/{slug}.{'webp' if slug=='bunny-survival' else 'png'}" width="800" height="470" loading="lazy" alt="{name}"><span class="tag">{t(genre,gr)}</span><span class="round-arrow" aria-hidden="true">↗</span></a><div class="game-copy"><span class="micro">0{i+1} / {t('PLAYABLE DEMO','ИГРОВОЕ ДЕМО')}</span><h3><a href="{slug}.html">{name}</a></h3><p>{t(tag,tr)}</p><a class="text-link" href="{slug}.html">{t('Explore game','Об игре')} <span>↗</span></a></div></article>'''
 body=f'''<section class="hero"><div class="hero-art" aria-hidden="true"></div><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> {t('A SERENDIPITY RESEARCH STUDIO','СТУДИЯ SERENDIPITY RESEARCH')}</div><h1>{t('Small games.<br>Big <em>smiles.</em>','Маленькие игры.<br>Большие <em>эмоции.</em>')}</h1><p>{t('We make colorful little worlds you’ll want to come back to. A casual game studio with curiosity at heart.','Создаём красочные миры, в которые хочется возвращаться. Казуальные игры, рождённые из любопытства.')}</p><div class="actions"><a class="button" href="#games">{t('Explore our games','Смотреть игры')} ↗</a><a class="subtle" href="#studio">{t('Meet the studio','Знакомьтесь: студия')} ↓</a></div></div><div class="hero-caption"><span class="dot"></span> {t('A LITTLE WONDER. EVERY DAY.','НЕМНОГО ЧУДА. КАЖДЫЙ ДЕНЬ.')}</div><a class="scroll" href="#games" aria-label="{t('Scroll to games','Перейти к играм')}">↓</a></section><div class="ticker" aria-hidden="true"><div>{('PLAYFUL BY NATURE ✳ MADE FOR THE WEB ✳ LITTLE WORLDS, BIG FEELINGS ✳ ' if not ru else 'ИГРА В НАШЕЙ ПРИРОДЕ ✳ СОЗДАНО ДЛЯ БРАУЗЕРА ✳ МАЛЕНЬКИЕ МИРЫ, БОЛЬШИЕ ЭМОЦИИ ✳ ')*4}</div></div><section class="section" id="games"><div class="section-head reveal"><div><span class="eyebrow">01 / {t('OUR GAMES','НАШИ ИГРЫ')}</span><h2>{t('Your next happy accident.','Ваша новая счастливая случайность.')}</h2></div><p>{t('Easy to jump into.<br>Hard to put down.','Легко начать.<br>Трудно оторваться.')}<br><span class="micro">{t('04 GAMES · IN DEVELOPMENT','04 ИГРЫ · В РАЗРАБОТКЕ')}</span></p></div><div class="games-grid">{cards}</div></section><section class="studio section" id="studio"><div class="studio-visual reveal"><img src="{p}assets/studio-mascot.png" alt="{t('Our cat mascot with an umbrella','Наш котик-маскот с зонтиком')}" loading="lazy" width="1672" height="941"><span class="studio-sticker">{t('Stay<br>curious.','Будьте<br>любопытны.')} ✳</span></div><div class="reveal"><span class="eyebrow">02 / {t('THE STUDIO','О СТУДИИ')}</span><h2>{t('Serious about<br>the little joys.','Серьёзно<br>о маленьких радостях.')}</h2><p>{t('We’re Serendipity Games, a casual browser game studio and part of Serendipity Research. We turn small, curious ideas into bright, approachable experiences.','Мы Serendipity Games — студия казуальных браузерных игр в составе Serendipity Research. Превращаем небольшие любопытные идеи в яркие и понятные игры.')}</p><p>{t('A satisfying merge. A perfectly timed jump. An unexpected discovery. These are the moments we build for.','Приятное слияние. Прыжок в нужную секунду. Неожиданное открытие. Ради таких моментов мы создаём игры.')}</p><a class="text-link" href="#partners">{t('Let’s make something playful','Создадим что-нибудь вместе')} ↗</a></div></section><section class="values section"><div class="reveal"><b>✦</b><h3>{t('Instantly inviting','Легко увлечься')}</h3><p>{t('Clear ideas and intuitive play. The fun starts with the first click.','Понятные идеи и интуитивная игра. Всё начинается с первого клика.')}</p></div><div class="reveal"><b>◒</b><h3>{t('Full of character','С характером')}</h3><p>{t('Expressive little worlds, warm personalities and a splash of the unexpected.','Выразительные миры, добрые персонажи и немного неожиданностей.')}</p></div><div class="reveal"><b>↗</b><h3>{t('Made to explore','Простор для открытий')}</h3><p>{t('We build, play and refine, finding the small details that make a game feel right.','Создаём, играем и дорабатываем детали, из которых складывается удовольствие.')}</p></div></section><section class="section journal" id="journal"><div class="section-head reveal"><div><span class="eyebrow">03 / {t('INSIDE THE STUDIO','ВНУТРИ СТУДИИ')}</span><h2>{t('A peek behind the play.','По ту сторону игры.')}</h2></div><p>{t('Explore what we’re making.','Загляните в наши проекты.')}</p></div><div class="journal-grid"><a class="journal-card reveal" href="bunny-survival.html"><img src="{p}assets/bunny-survival.webp" loading="lazy" width="800" height="470" alt="Bunny Survival"><div><span class="micro">{t('GAME SPOTLIGHT','ЗНАКОМСТВО С ИГРОЙ')}</span><h3>{t('A small bunny takes on the horde.','Маленький кролик против целой орды.')} ↗</h3></div></a><a class="journal-card reveal" href="bunny-runner.html"><img src="{p}assets/bunny-runner.png" loading="lazy" width="800" height="470" alt="Bunny Runner"><div><span class="micro">{t('IN DEVELOPMENT','В РАЗРАБОТКЕ')}</span><h3>{t('One bunny. A world of possibilities.','Один кролик. Мир возможностей.')} ↗</h3></div></a></div></section><section class="partners section reveal" id="partners"><span class="eyebrow">04 / {t('FOR PARTNERS','ПАРТНЁРАМ')}</span><h2>{t('Good things<br>happen <em>together.</em>','Хорошее случается<br><em>вместе.</em>')}</h2><p>{t('Publishing, distribution or a new creative collaboration.<br>Discover our games and the worlds we’re building.','Издание, дистрибуция или новое творческое сотрудничество.<br>Познакомьтесь с играми и мирами, которые мы создаём.')}</p><a class="button" href="mailto:hello@serendipity-games.com">hello@serendipity-games.com ↗</a><div class="partner-tags"><span>{t('Publishing','Издание')}</span><span>{t('Distribution','Дистрибуция')}</span><span>{t('Creative collaboration','Совместная разработка')}</span></div><span class="partner-star" aria-hidden="true">✳</span></section>'''
 (folder/'index.html').write_text(shell(body))
 for g in GAMES:
  slug,name,genre,gr,tag,tr,desc,dr,color=g
  body=f'''<section class="section detail"><a class="text-link" href="./#games">← {t('All games','Все игры')}</a><div class="detail-grid"><div><span class="eyebrow">{t(genre,gr)} / {t('IN DEVELOPMENT','В РАЗРАБОТКЕ')}</span><h1>{name}</h1><h2>{t(tag,tr)}</h2><p>{t(desc,dr)}</p><a class="button" href="{p}play.html?game={slug}&lang={lang}">{t('Play demo','Играть в демо')} ↗</a><p class="micro">{t('BROWSER GAME · NO DOWNLOAD','БРАУЗЕРНАЯ ИГРА · БЕЗ УСТАНОВКИ')}</p></div><img class="detail-art" src="{p}assets/{slug}.{'webp' if slug=='bunny-survival' else 'png'}" width="800" height="470" alt="{name}"></div><div class="demo-note"><h3>{t('A little preview of what’s next.','Первое знакомство с будущей игрой.')}</h3><p>{t('This is a playable development build. Content and balancing may change; demo rewards may be simulated. The game interface may be in English.','Это игровая сборка в разработке. Контент и баланс могут измениться; награды в демо могут быть условными. Интерфейс игры может быть на английском.')}</p></div></section><section class="section"><h2>{t('More little worlds.','Больше маленьких миров.')}</h2><div class="related">{''.join(f'<a class="text-link" href="{x[0]}.html">{x[1]} ↗</a>' for x in GAMES if x!=g)}</div></section>'''
  (folder/f'{slug}.html').write_text(shell(body,f'{slug}.html',name))

# Preserve links shared before the portfolio replacement.
for folder,lang in ((ROOT,'en'),(ROOT/'ru','ru')):
 (folder/'raindrops.html').write_text(f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url=bunny-survival.html"><link rel="canonical" href="https://serendipity-games.com/{'ru/' if lang=='ru' else ''}bunny-survival.html"><title>Bunny Survival — Serendipity Games</title></head><body><a href="bunny-survival.html">Bunny Survival →</a></body></html>''')
